// This endpoint is ready.
app.MapGet("/", () => "Welcome to the Grove notice board!");

// 2. Add an endpoint for GET /hello that
//    answers: Hello from the Grove!
app.MapGet("/hello", () => "Hello from the Grove!");

// 3. Add an endpoint for GET /notice that
//    answers with an object: title "Frog race",
//    day "Saturday"
app.MapGet("/notice", () => new { title = "Frog race", day = "Saturday" });

// 1. Start the server here, on the last line.
app.Run();

