var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

var laps = new List<Lap> { new(1, 31.2), new(2, 30.8) };
var seasonOpen = false;

app.MapGet("/", () => "Skyline Racers API");

app.MapGet("/laps", () => laps);

app.MapGet("/season", () => seasonOpen
    ? Results.Ok(new { season = 3 })
    : Results.Problem("Season 3 starts on Friday.", statusCode: 409));

app.Run();

record Lap(int LapNumber, double Seconds);

