var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

var version = new AppVersion("Skyline Racers", "2.4.1");
var maintenance = true;

// TODO 1: the load balancer wants plain text
// "Healthy", not JSON.
app.MapGet("/health", () => "Healthy");

// TODO 2: clients want JSON:
// { "name": "...", "version": "..." }
app.MapGet("/version", () => version);

// TODO 3: while maintenance is true, answer 503
// problem details: "Servers are down for
// maintenance." Otherwise: "Let's race!"
app.MapGet("/play", () => maintenance
    ? Results.Problem("Servers are down for maintenance.", statusCode: 503)
    : Results.Text("Let's race!"));

app.Run();

record AppVersion(string Name, string Version);
